/// <summary>
/// This is an extension class for <c>TaxRegistration</c> table.
/// </summary>
[ExtensionOf(tableStr(TaxRegistration))]
final class METTaxRegistration_Extension
{
}

Method.Source:
/// <summary>
/// Validates the field values for tax registration
/// </summary>
/// <param name = "_fieldIdToCheck">_fieldIdToCheck</param>
/// <returns>A boolean value.</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = next validateWrite();

    if (this.METPermitStartDate > this.METPermitExpiryDate)
    {
        ret = checkFailed("@MET:PermitStartDateErr");
    }

    return ret;
}
